#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_update_non_head_all_non_zero(void) {
    // Setup: create a linked list with at least two nodes
    // We will update the second node with all non-zero values
    node *root = NULL;
    insert(&root, 1, 0, 5, 1);   // ID=1, AT=0, BT=5, priority=1
    insert(&root, 2, 1, 4, 2);   // ID=2, AT=1, BT=4, priority=2
    // Ensure list is built
    TEST_ASSERT_NOT_NULL(root);
    TEST_ASSERT_NOT_NULL(root->next);

    // Initialize the target node's fields to known values (should be 0 from insert)
    node *target = root->next;
    TEST_ASSERT_EQUAL_INT(2, target->ID);
    TEST_ASSERT_EQUAL_INT(0, target->CT);
    TEST_ASSERT_EQUAL_INT(0, target->WT);
    TEST_ASSERT_EQUAL_INT(0, target->TAT);

    // Test: update the second node (non-head) with all non-zero values
    // This triggers path 5: head condition false, traverse loop, then all three updates
    update(&root, 2, 100, 200, 300);  // ct=100, wt=200, tat=300 (all non-zero)

    // Assertions: verify all three fields were updated
    TEST_ASSERT_EQUAL_INT(100, target->CT);
    TEST_ASSERT_EQUAL_INT(200, target->WT);
    TEST_ASSERT_EQUAL_INT(300, target->TAT);

