    TEST_ASSERT_EQUAL_INT(1, root->ID);
    TEST_ASSERT_EQUAL_INT(0, root->CT);
    TEST_ASSERT_EQUAL_INT(0, root->WT);
    TEST_ASSERT_EQUAL_INT(0, root->TAT);

    // Cleanup
    helper_cleanup_process_queue(&root);
